1. verus! {
2. 
3. use crate::mm::phys::phys_view;
4. 
5. //==================================================================================================
6. // Global-token attachment (deferred to the proving phase)
7. //==================================================================================================
8. 
9. /// The manager brokers the *global* frame partition: its abstract view coincides with
10. /// `phys_view().frames`. This is the §8 ghost-token attachment; the proving phase realizes it
11. /// with a token over the `frame::INSTANCE` / `PhysMemoryManager` singletons.
12. pub proof fn lemma_manager_attached(m: &PhysMemoryManager)
13.     ensures
14.         m@ == phys_view().frames,
15. {
16.     admit();
17. }
18. 
19. //==================================================================================================
20. // Kernel-path transitions (frame::alloc / frame::alloc_contiguous take no `self`)
21. //==================================================================================================
22. 
23. /// Effect of a single kernel-frame allocation on the brokered partition: the freshly returned
24. /// `addr` was free and becomes reserved with refcount 1. `frame::alloc` carries no `self`, so the
25. /// link to `self@` is supplied here and discharged by the global-token attachment in the proving
26. /// phase.
27. pub proof fn lemma_kernel_alloc_one(pre: FrameAllocView, post: FrameAllocView, addr: int)
28.     requires
29.         pre.wf(),
30.     ensures
31.         pre.free_frames.contains(addr),
32.         post == pre.alloc_one(addr),
33.         post.wf(),
34. {
35.     admit();
36. }
37. 
38. /// Effect of a contiguous kernel-frame allocation: `frames` owns `count` physically contiguous
39. /// frames starting at some page-aligned `base`, all of which were free and become reserved.
40. pub proof fn lemma_kernel_alloc_contiguous(
41.     pre: FrameAllocView,
42.     post: FrameAllocView,
43.     frames: Seq<KernelFrame>,
44.     count: nat,
45. )
46.     requires
47.         pre.wf(),
48.     ensures
49.         frames.len() == count,
50.         crate::mm::phys::manager::kernel_frames_contiguous(frames, count),
51.         post == pre.book_all(crate::mm::phys::manager::kernel_addr_set(frames)),
52.         pre.all_free(crate::mm::phys::manager::kernel_addr_set(frames)),
53.         post.wf(),
54. {
55.     admit();
56. }
57. 
58. /// The base address returned by a contiguous allocation, advanced by any in-range frame index,
59. /// stays within the address space — `frame::alloc_contiguous` guarantees the whole `count`-frame
60. /// span fits a `usize`, so no intermediate offset overflows. Admitted here; the proving phase
61. /// derives it from the contiguous allocator's range bound.
62. pub proof fn lemma_contig_no_overflow(base_raw: usize, idx: usize, count: usize)
63.     requires
64.         idx < count,
65.         base_raw as int + (count as int) * spec_page_size() <= usize::MAX as int,
66.     ensures
67.         (idx as int) * spec_page_size() <= usize::MAX as int,
68.         base_raw as int + (idx as int) * spec_page_size() <= usize::MAX as int,
69. {
70.     // `spec_page_size()` is a `usize`-derived value, hence non-negative, and `idx < count`,
71.     // so multiplying the inequality `idx <= count` by `spec_page_size()` preserves it.
72.     vstd::arithmetic::mul::lemma_mul_inequality(
73.         idx as int,
74.         count as int,
75.         spec_page_size(),
76.     );
77. }
78. 
79. //==================================================================================================
80. // User bulk-path transitions
81. //==================================================================================================
82. 
83. /// The address set of a length-zero handle sequence is empty.
84. pub proof fn lemma_user_addr_set_empty(frames: Seq<UserFrame>)
85.     requires
86.         frames.len() == 0,
87.     ensures
88.         user_addr_set(frames) == Set::<int>::empty(),
89.         user_addr_set(frames).finite(),
90.         user_addr_set(frames).len() == 0,
91. {
92.     broadcast use vstd::set::group_set_axioms;
93.     assert(user_addr_set(frames) =~= Set::<int>::empty());
94. }
95. 
96. /// Pushing a handle extends the owned-address set by exactly that handle's address.
97. pub proof fn lemma_user_addr_set_push(frames: Seq<UserFrame>, uf: UserFrame)
98.     ensures
99.         user_addr_set(frames.push(uf)) =~= user_addr_set(frames).insert(uf@),
100. {
101.     let extended = frames.push(uf);
102.     assert forall|a: int| #[trigger] user_addr_set(extended).contains(a) implies
103.         user_addr_set(frames).insert(uf@).contains(a) by {
104.         let i = choose|i: int| #![trigger extended[i]@] 0 <= i < extended.len() && extended[i]@ == a;
105.         if i < frames.len() {
106.             assert(frames[i]@ == a);
107.         }
108.     }
109.     assert forall|a: int| #[trigger] user_addr_set(frames).insert(uf@).contains(a) implies
110.         user_addr_set(extended).contains(a) by {
111.         if a == uf@ {
112.             assert(extended[frames.len() as int]@ == a);
113.         } else {
114.             let i = choose|i: int| #![trigger frames[i]@] 0 <= i < frames.len() && frames[i]@ == a;
115.             assert(extended[i]@ == a);
116.         }
117.     }
118. }
119. 
120. /// Reserving the empty set leaves the partition unchanged.
121. pub proof fn lemma_book_all_empty(v: FrameAllocView)
122.     ensures
123.         v.book_all(Set::<int>::empty()) == v,
124. {
125.     assert(v.book_all(Set::<int>::empty()).allocated_frames =~= v.allocated_frames);
126.     assert(v.book_all(Set::<int>::empty()).free_frames =~= v.free_frames);
127.     assert(v.book_all(Set::<int>::empty()).refcounts =~= v.refcounts);
128. }
129. 
130. /// Booking a set and then allocating one further frame equals booking the enlarged set.
131. /// This is the algebraic step that lets the per-iteration `alloc_one` transitions of
132. /// `Upool::alloc` accumulate into a single `book_all` over the whole address set.
133. pub proof fn lemma_book_all_alloc_one(v: FrameAllocView, s: Set<int>, a: int)
134.     ensures
135.         v.book_all(s).alloc_one(a) == v.book_all(s.insert(a)),
136. {
137.     assert(v.book_all(s).alloc_one(a).allocated_frames
138.         =~= v.book_all(s.insert(a)).allocated_frames);
139.     assert(v.book_all(s).alloc_one(a).free_frames =~= v.book_all(s.insert(a)).free_frames);
140.     assert(v.book_all(s).alloc_one(a).refcounts =~= v.book_all(s.insert(a)).refcounts);
141. }
142. 
143. /// Loop invariant for the user bulk-allocation loop: the handles accumulated so far own a
144. /// finite set of *distinct* addresses, all of which were free in the pre-call partition
145. /// `g_old`, and the current partition `mview` is exactly `g_old` with that set booked.
146. pub open spec fn user_bulk_inv(
147.     g_old: FrameAllocView,
148.     mview: FrameAllocView,
149.     frames: Seq<UserFrame>,
150. ) -> bool {
151.     &&& user_addr_set(frames).finite()
152.     &&& user_addr_set(frames).len() == frames.len()
153.     &&& g_old.all_free(user_addr_set(frames))
154.     &&& mview == g_old.book_all(user_addr_set(frames))
155. }
156. 
157. /// Base case: before any allocation the invariant holds with the partition untouched.
158. pub proof fn lemma_user_bulk_base(g_old: FrameAllocView, frames: Seq<UserFrame>)
159.     requires
160.         frames.len() == 0,
161.     ensures
162.         user_bulk_inv(g_old, g_old, frames),
163. {
164.     lemma_user_addr_set_empty(frames);
165.     lemma_book_all_empty(g_old);
166. }
167. 
168. /// Inductive step: one successful `Upool::alloc` (which moved the currently-free `uf@` from
169. /// free to allocated, i.e. `mview -> mview.alloc_one(uf@)`) preserves the invariant for the
170. /// extended handle sequence.
171. pub proof fn lemma_user_bulk_step(
172.     g_old: FrameAllocView,
173.     mview: FrameAllocView,
174.     frames: Seq<UserFrame>,
175.     uf: UserFrame,
176. )
177.     requires
178.         user_bulk_inv(g_old, mview, frames),
179.         mview.free_frames.contains(uf@),
180.     ensures
181.         user_bulk_inv(g_old, mview.alloc_one(uf@), frames.push(uf)),
182. {
183.     broadcast use vstd::set::group_set_axioms;
184. 
185.     let s = user_addr_set(frames);
186.     // `mview == g_old.book_all(s)`, so `mview.free_frames == g_old.free_frames.difference(s)`.
187.     // `uf@` being free in `mview` therefore means it is free in `g_old` and not yet in `s`.
188.     assert(mview.free_frames =~= g_old.free_frames.difference(s));
189.     assert(g_old.free_frames.contains(uf@) && !s.contains(uf@));
190. 
191.     lemma_user_addr_set_push(frames, uf);
192.     lemma_book_all_alloc_one(g_old, s, uf@);
193. 
194.     let s2 = user_addr_set(frames.push(uf));
195.     assert(s2 =~= s.insert(uf@));
196.     // Distinctness: `uf@ ∉ s`, so the cardinality grows by exactly one.
197.     assert(s2.len() == s.len() + 1);
198.     assert(frames.push(uf).len() == frames.len() + 1);
199.     // Every address in the enlarged set was free in `g_old`.
200.     assert forall|x: int| #[trigger] s2.contains(x) implies g_old.free_frames.contains(x) by {
201.         if x != uf@ {
202.             assert(s.contains(x));
203.         }
204.     }
205. }
206. 
207. /// On a mid-bulk failure the implementation `clear()`s the vector, which drops (and thus frees)
208. /// every frame already taken, restoring the partition to its pre-call state. `Drop` side effects
209. /// are not modeled in exec, so the restoration is asserted here.
210. pub proof fn lemma_user_bulk_err_restored(m: &PhysMemoryManager, pre: FrameAllocView)
211.     requires
212.         pre.wf(),
213.     ensures
214.         m@ == pre,
215. {
216.     admit();
217. }
218. 
219. } // verus!
220.

